My best shot so far:

1. writing a decorator function that checks if there is a parameter "st_state_params". The dict is run through checking if it is a session_state key reference or if it is a function that needs to be excecuted. Sometimes a function is needed to perform calculations on multiple session_state variables together.
2. Adding the decorator to the DB functions.
3. Adding some complex parameters to the kwargs of the submit button of the form.

```python

def translate_session_state_keys(func):
    """
    > It takes a function and returns a new function that will call the original function with the
    values of the session state variables passed as keyword arguments

    Args:
      func: The function to be decorated.

    Returns:
      A function that takes in a function and returns a function.
    """

    @wraps(func)
    def wrapper(*args, **kwargs):

        new_kwargs = kwargs
        _session_state_kwargs = new_kwargs.pop("st_state_params", {})
        new_kwargs.update(
            {
                param: st.session_state[session_key]
                if isinstance(session_key, str)
                else session_key()
                if callable(session_key)
                else None  # error prone
                for param, session_key in _session_state_kwargs.items()
            }
        )

        return func(*args, **new_kwargs)

    return wrapper

@translate_session_state_keys
def some_db_function(_conn, id: list[int]) -> None:

    pass

with st.form(key="master_data_bl_ids_to_delete", clear_on_submit=True):

    st.text_area(label="IDs", key="master_data_bl_references")

    if st.form_submit_button(
        label="Delete",
        on_click=some_db_function,
        kwargs=dict(
            _conn=get_db_session(settings.DEFAULT.DB.get(env)),
            st_state_params=dict(
                ids=lambda: [
                    int(x)
                    for x in filter(lambda y: y != "", re.split(pattern=r"[\s|,|;|\n]", string=st.session_state.master_data_bl_references))
                ]
            ),
        ),
    ):

